from array import array
from dataclasses import replace
from pathlib import Path
import tempfile
import unittest
from unittest import mock

from tools.can_dashboard import excerpt, model, recording, replay, sources
from tools.can_dashboard.replay import ReplayError, ReplayPlayer
from tools.logs import mlvlg


PEAK_TRC = """;$FILEVERSION=1.1
;$STARTTIME=46250.0
;
; Generated by PCAN-View v5.3
     1)         2.6  Rx         0180  8  00 10 00 00 00 00 00 00
     2)         5.0  Rx         0123  8  00 00 00 00 00 00 00 00
     3)        12.8  Rx         06F0  8  08 01 02 03 04 05 06 07
     4)        13.0  Error      0008  4  00 19 08 08
"""


def feed_group(dashboard, group, base_time):
    snapshot = None
    for index, frame in enumerate(group):
        result = dashboard.process_frame(
            frame,
            now=base_time + index * 0.00025,
        )
        if result is not None:
            snapshot = result
    return snapshot


def frame_timeline(times, can_id=0x6F0, frames=None):
    """A frame timeline of one 0x280 frame per time unless frames are given."""
    frames = frames or [(0x280, bytes(8)) for _ in times]
    timeline = replay.FrameTimeline(
        "synthetic.trc",
        "TRC",
        array("d", times),
        array("H", [frame_id for frame_id, _data in frames]),
        array("B", [0] * len(frames)),
        [data for _frame_id, data in frames],
        can_id,
    )
    timeline.build_checkpoints()
    return timeline


class LoadTimelineTest(unittest.TestCase):
    def load(self, name, content):
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / name
            path.write_text(content, encoding="ascii")
            return replay.load_timeline(path, 0x6F0)

    def test_peak_trc_keeps_consumed_frames_and_error_records(self):
        timeline = self.load("capture.trc", PEAK_TRC)
        self.assertEqual(timeline.kind, "TRC")
        self.assertEqual(list(timeline.ids), [0x180, 0x6F0, 0])
        self.assertEqual(list(timeline.times), [0.0026, 0.0128, 0.013])
        self.assertEqual(timeline.duration, 0.013)
        frame = timeline.item(1, received=4.5)
        self.assertEqual(frame.data, bytes.fromhex("0801020304050607"))
        self.assertEqual(frame.timestamp, 0.0128)
        self.assertEqual(frame.received_monotonic, 4.5)
        self.assertFalse(frame.is_error_frame)
        self.assertTrue(timeline.item(2).is_error_frame)

    def test_a_cp1251_header_comment_replays_and_survives_an_excerpt(self):
        comment = "; \u0417\u0430\u043f\u0438\u0441\u044c \u0441\u0442\u0435\u043d\u0434\u0430\n"
        content = PEAK_TRC.replace(";\n", comment, 1).encode("cp1251")
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "capture.trc"
            path.write_bytes(content)
            timeline = replay.load_timeline(path, 0x6F0)
            self.assertEqual(list(timeline.ids), [0x180, 0x6F0, 0])
            output = Path(directory) / "excerpt.trc"
            saved = excerpt.save_excerpt(timeline, 0.0, 0.0128, output)
            self.assertEqual(saved.records, 3)
            self.assertIn(comment.encode("cp1251"), output.read_bytes())

    def test_candump_times_start_at_the_first_line(self):
        timeline = self.load(
            "capture.log",
            "(12.500000) can0 6F0#0801020304050607\n"
            "(12.600000) can0 280#0000000000100000\n",
        )
        self.assertEqual(timeline.kind, "candump")
        self.assertEqual(list(timeline.ids), [0x6F0, 0x280])
        self.assertEqual(len(timeline), 2)
        self.assertEqual(timeline.times[0], 0.0)
        self.assertAlmostEqual(timeline.times[1], 0.1, places=9)

    def test_a_file_without_replay_items_is_rejected(self):
        with self.assertRaisesRegex(ReplayError, "nothing to replay"):
            self.load("empty.log", "")

    def test_a_missing_file_is_a_replay_error(self):
        with self.assertRaises(ReplayError):
            replay.load_timeline(Path("missing-capture.trc"), 0x6F0)


class LoadReplayTest(unittest.TestCase):
    def load(self, outcome):
        events = []
        with mock.patch.object(replay, "load_timeline", **outcome):
            replay.load_replay(
                Path("capture.trc"), 0x6F0, "tuning", None, events.append
            )
        return events

    def test_every_loader_failure_ends_with_an_error_status(self):
        for error in (
            ReplayError("nothing to replay"),
            ValueError("bad value"),
            OSError("device not ready"),
            MemoryError(),
            KeyError("tick16"),
            RuntimeError("unexpected"),
        ):
            with self.subTest(error=type(error).__name__):
                (event,) = self.load({"side_effect": error})
                self.assertIsInstance(event, sources.SourceStatus)
                self.assertEqual(event.state, "error")
                self.assertTrue(event.detail.startswith("replay failed: "))

    def test_a_loaded_timeline_is_emitted(self):
        timeline = object()
        self.assertEqual(
            self.load({"return_value": timeline}),
            [replay.ReplayLoaded(timeline)],
        )


class RecordingReplayTest(unittest.TestCase):
    def test_mlg_records_restore_the_recorded_values(self):
        generator = model.DemoGenerator()
        source = model.DashboardModel("tuning", 0x6F0, 1)
        recorded = []
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / "drive.mlg"
            recorder = recording.TelemetryMlgRecorder(
                output,
                "tuning",
                1_776_000_000,
            )
            for tick in range(1, 7):
                elapsed = (tick - 1) * 0.1 + (1.0 if tick > 3 else 0.0)
                for frame in generator.stock_context(tick, elapsed):
                    source.process_frame(frame, now=elapsed)
                feed_group(source, generator.group(tick, elapsed), elapsed)
                recorder.append(source, elapsed)
                recorded.append((elapsed, source.value("rpm")))
            summary = recorder.close()
            timeline = replay.load_timeline(output, 0x6F0)

        self.assertGreater(summary.bridge_records, 0)
        self.assertEqual(timeline.kind, "MLG")
        self.assertEqual(len(timeline), 6)
        for index, (elapsed, _rpm) in enumerate(recorded):
            self.assertAlmostEqual(timeline.times[index], elapsed, places=3)
        target = model.DashboardModel("tuning", 0x6F0, 1)
        for index in range(len(timeline)):
            snapshot = target.process_record(timeline.item(index, 10.0), 10.0)
            self.assertIsNotNone(snapshot)
            self.assertEqual(snapshot.tick16, index + 1)
            self.assertAlmostEqual(
                target.value("rpm"),
                recorded[index][1],
                places=3,
            )
        self.assertEqual(target.stats(10.0).completed_groups, 6)
        self.assertEqual(target.missed_snapshots, 0)
        self.assertEqual(target.stock_rpm, source.stock_rpm)
        self.assertIsNotNone(source.tcm_gear)
        self.assertEqual(target.tcm_gear, source.tcm_gear)
        self.assertAlmostEqual(
            target.vehicle_speed_kmh,
            source.vehicle_speed_kmh,
            places=3,
        )

    def test_a_channel_named_with_the_candidate_marker_replays_under_its_source(self):
        bindings = recording.build_bindings("tuning")
        specs = tuple(
            replace(binding.spec, name=binding.spec.name + "*")
            if binding.source == "af_adjustment_b1_raw"
            else binding.spec
            for binding in bindings
        )
        sources = [binding.source for binding in bindings]
        with tempfile.TemporaryDirectory() as directory:
            output = Path(directory) / "earlier.mlg"
            with output.open("wb") as stream:
                writer = mlvlg.StreamWriter(stream, specs, 1_776_000_000)
                values = [1] * len(specs)
                values[sources.index("af_adjustment_b1_raw")] = -2
                writer.write(tuple(values), 0.0)
            timeline = replay.load_timeline(output, 0x6F0)

        record = timeline.item(0, 10.0)
        self.assertEqual(record.values["af_adjustment_b1_raw"], -2)


class CheckpointTest(unittest.TestCase):
    def test_a_restored_observer_matches_a_full_pass(self):
        speed = []
        times = []
        for step in range(900):
            time = step * 0.02
            kmh = 0.0 if time < 1.0 else min(12.5 * (time - 1.0), 150.0)
            payload = bytearray(8)
            payload[4:6] = int(kmh * 100).to_bytes(2, "big")
            speed.append((0x280, bytes(payload)))
            times.append(time)
        timeline = frame_timeline(times, frames=speed)
        for index in (0, 1, 49, 50, 51, 460, 899):
            with self.subTest(index=index):
                restored = timeline.drive_at(index)
                full = model.DriveObserver(0x6F0)
                for item in range(index):
                    timeline.observe(full, item)
                for restored_run, full_run in zip(
                    restored.acceleration.runs,
                    full.acceleration.runs,
                ):
                    self.assertEqual(restored_run.state, full_run.state)
                    self.assertEqual(restored_run.last, full_run.last)
                    self.assertEqual(
                        restored_run.started_at,
                        full_run.started_at,
                    )
        run = timeline.drive_at(len(timeline)).acceleration.run("0-100")
        self.assertAlmostEqual(run.last.seconds, 9.0 - 1.02, places=2)


class ReplayPlayerTest(unittest.TestCase):
    def setUp(self):
        self.timeline = frame_timeline([step / 10 for step in range(101)])

    def test_a_seek_returns_the_warm_up_range_before_the_target(self):
        player = ReplayPlayer(self.timeline)
        first, last = player.seek(5.0, 100.0)
        self.assertEqual(self.timeline.times[first], 5.0 - replay.WARMUP_SECONDS)
        self.assertEqual(self.timeline.times[last - 1], 5.0)
        self.assertEqual(player.position, 5.0)
        self.assertEqual(player.seek(-3.0, 100.0), (0, 1))
        self.assertEqual(player.seek(99.0, 100.0)[1], len(self.timeline))

    def test_playback_follows_the_window_clock_at_the_chosen_speed(self):
        player = ReplayPlayer(self.timeline)
        player.seek(5.0, 100.0)
        self.assertEqual(player.advance(101.0), (51, 51, False))
        player.play(100.0)
        first, last, ended = player.advance(101.0)
        self.assertEqual((first, last, ended), (51, 61, False))
        self.assertAlmostEqual(player.position, 6.0)
        player.set_speed(2.0, 101.0)
        first, last, ended = player.advance(102.0)
        self.assertEqual((first, last, ended), (61, 81, False))
        self.assertAlmostEqual(player.host_time(7.0, 102.0), 101.5)
        first, last, ended = player.advance(103.5)
        self.assertEqual((last, ended), (101, True))
        self.assertEqual(player.position, 10.0)
        self.assertTrue(player.at_stop())

    def test_a_loop_region_stops_at_its_out_point(self):
        player = ReplayPlayer(self.timeline, loop=True)
        player.seek(4.0, 0.0)
        player.set_loop_out()
        player.seek(2.0, 0.0)
        player.set_loop_in()
        self.assertEqual(player.region(), (2.0, 4.0))
        player.play(0.0)
        first, last, ended = player.advance(5.0)
        self.assertTrue(ended)
        self.assertEqual(player.position, 4.0)
        self.assertEqual(self.timeline.times[last - 1], 4.0)

    def test_playback_beyond_the_loop_region_runs_to_the_end(self):
        player = ReplayPlayer(self.timeline, loop=True)
        player.seek(4.0, 0.0)
        player.set_loop_out()
        player.seek(6.0, 0.0)
        player.play(0.0)
        _first, last, ended = player.advance(3.0)
        self.assertFalse(ended)
        self.assertEqual(self.timeline.times[last - 1], 9.0)
        player.loop = False
        player.seek(3.0, 0.0)
        player.play(0.0)
        self.assertFalse(player.advance(1.5)[2])
        self.assertAlmostEqual(player.position, 4.5)

    def test_the_region_end_bounds_the_position_inside_the_loop(self):
        player = ReplayPlayer(self.timeline)
        player.seek(10.0, 0.0)
        self.assertTrue(player.past_region())
        player.seek(4.0, 0.0)
        player.set_loop_out()
        self.assertTrue(player.past_region())
        player.seek(3.9, 0.0)
        self.assertFalse(player.past_region())
        player.seek(6.0, 0.0)
        self.assertTrue(player.past_region())

    def test_loop_points_never_cross(self):
        player = ReplayPlayer(self.timeline)
        player.seek(3.0, 0.0)
        player.set_loop_out()
        player.seek(5.0, 0.0)
        player.set_loop_in()
        self.assertEqual((player.loop_in, player.loop_out), (5.0, None))
        player.seek(1.0, 0.0)
        player.set_loop_out()
        self.assertEqual((player.loop_in, player.loop_out), (None, 1.0))

    def test_a_dense_stretch_falls_behind_instead_of_skipping(self):
        count = replay.MAX_ITEMS_PER_STEP * 2 + 10
        timeline = frame_timeline([index * 1e-4 for index in range(count)])
        player = ReplayPlayer(timeline)
        player.seek(0.0, 0.0)
        player.play(0.0)
        first, last, ended = player.advance(10.0)
        self.assertEqual(last - first, replay.MAX_ITEMS_PER_STEP)
        self.assertFalse(ended)
        self.assertEqual(player.position, timeline.times[last - 1])
        first, last, ended = player.advance(20.0)
        self.assertEqual(last - first, replay.MAX_ITEMS_PER_STEP)

    def test_the_speed_cycles_through_the_offered_steps(self):
        self.assertEqual(replay.next_speed(1.0), 2.0)
        self.assertEqual(replay.next_speed(3.0), 4.0)
        self.assertEqual(replay.next_speed(8.0), 0.25)
        self.assertEqual(replay.next_speed(100.0), 0.25)


if __name__ == "__main__":
    unittest.main()
